26	@Injectable()
27	export class GoogleOAuthService {
28	  private readonly audience: string;
29	  private readonly keys: jose.JWTVerifyGetKey;
30	
31	  // `keys` is a test seam for a fake JWKS. Nest reads every constructor
32	  // position from `design:paramtypes`, where an interface type emits no
33	  // injectable token — `@Optional()` is what makes it inject `undefined`
34	  // instead of refusing to resolve the provider.
35	  constructor(configService: ConfigService, @Optional() keys?: jose.JWTVerifyGetKey) {
36	    const nodeEnv = configService.get<string>('NODE_ENV') ?? 'development';
37	    const clientId = configService.get<string>('GOOGLE_CLIENT_ID')?.trim();
38	    if (!clientId && nodeEnv !== 'development' && nodeEnv !== 'test') {
39	      throw new Error(`GOOGLE_CLIENT_ID is required when NODE_ENV is '${nodeEnv}'`);
40	    }
41	    this.audience = clientId || UNCONFIGURED_AUDIENCE;
42	    this.keys = keys ?? jose.createRemoteJWKSet(new URL(GOOGLE_JWKS_URL));
43	  }
