1	/**
2	 * The shell's login chrome. Framework-free: this window is the front door and a
3	 * status line, and the vault UI lives on the web app.
4	 *
5	 * Which methods appear is read off the flow, never branched on here, so a
6	 * method this host cannot collect renders no affordance at all (ADR 0008 D2).
7	 */
8	
9	import type { IdentityMethod } from '@cipherbox/login';
10	
11	export interface ShellModel {
12	  phase: 'starting' | 'signedOut' | 'signedIn';
13	  /** True while a restore, login, or logout is in flight. */
14	  busy: boolean;
15	  /** The methods the login flow offers, in the order to show them. */
16	  methods: readonly IdentityMethod[];
17	  /** The signed-in address, when the method carried one. */
18	  email: string | null;
19	  error: string | null;
20	  /** True once CipherBox has sent a code to the address in the form. */
21	  codeSent: boolean;
22	  /** The address the form holds, kept across a re-render. */
23	  address: string;
24	}
25	
26	export interface ShellActions {
27	  google(): void;
28	  sendEmailCode(email: string): void;
29	  submitEmailCode(email: string, code: string): void;
30	  logout(): void;
31	}
32	
33	type Renderer = (model: ShellModel, actions: ShellActions) => HTMLElement;
34	
35	/** One renderer per method the shell can collect. */
36	const RENDERERS: Partial<Record<IdentityMethod, Renderer>> = {
37	  google: googleButton,
38	  email: emailForm,
39	};
40	
41	export function renderShell(root: HTMLElement, model: ShellModel, actions: ShellActions): void {
42	  const view = element('div', { class: 'shell' });
43	  view.append(text('h1', 'CipherBox'));
44	
45	  if (model.phase === 'starting') view.append(note('Starting…'));
46	  else if (model.phase === 'signedIn') view.append(signedIn(model, actions));
47	  else view.append(frontDoor(model, actions));
48	
49	  if (model.error !== null) {
50	    view.append(text('p', model.error, { class: 'error', role: 'alert' }));
51	  }
52	  root.replaceChildren(view);
53	}
54	
55	function frontDoor(model: ShellModel, actions: ShellActions): HTMLElement {
56	  const section = element('section', { class: 'front-door' });
57	  section.append(note('Sign in to connect this device to your vault.'));
58	
59	  const offered = model.methods.flatMap((method) => {
60	    const render = RENDERERS[method];
61	    return render ? [render(model, actions)] : [];
62	  });
63	  if (offered.length === 0) {
64	    section.append(note('This build has no sign-in method configured.'));
65	  }
66	  section.append(...offered);
67	  return section;
68	}
69	
70	function googleButton(model: ShellModel, actions: ShellActions): HTMLElement {
71	  const button = text('button', 'Continue with Google', {
72	    'data-method': 'google',
73	    type: 'button',
74	  }) as HTMLButtonElement;
75	  button.disabled = model.busy;
76	  button.addEventListener('click', () => actions.google());
77	  return button;
78	}
79	
80	function emailForm(model: ShellModel, actions: ShellActions): HTMLElement {
81	  const form = element('form', { 'data-method': 'email' }) as HTMLFormElement;
82	
83	  const address = element('input', {
84	    name: 'email',
85	    type: 'email',
86	    placeholder: 'you@example.com',
87	    required: 'required',
88	    autocomplete: 'email',
89	  }) as HTMLInputElement;
90	  address.value = model.address;
91	  address.disabled = model.busy;
92	  form.append(address);
93	
94	  const code = element('input', {
95	    name: 'code',
96	    type: 'text',
97	    placeholder: 'Verification code',
98	    inputmode: 'numeric',
99	    autocomplete: 'one-time-code',
100	  }) as HTMLInputElement;
101	  code.disabled = model.busy;
102	
103	  const submit = text('button', model.codeSent ? 'Sign in' : 'Email me a code', {
104	    type: 'submit',
105	  }) as HTMLButtonElement;
106	  submit.disabled = model.busy;
107	
108	  if (model.codeSent) form.append(code);
109	  form.append(submit);
110	
111	  form.addEventListener('submit', (event) => {
112	    event.preventDefault();
113	    if (model.codeSent) actions.submitEmailCode(address.value, code.value);
114	    else actions.sendEmailCode(address.value);
115	  });
116	  return form;
117	}
118	
119	function signedIn(model: ShellModel, actions: ShellActions): HTMLElement {
120	  const section = element('section', { class: 'signed-in' });
121	  section.append(text('p', model.email ?? 'Signed in'));
122	  section.append(note('No vault on this device yet — the engine is not wired to this shell.'));
123	
124	  const out = text('button', 'Sign out', {
125	    'data-action': 'logout',
126	    type: 'button',
127	  }) as HTMLButtonElement;
128	  out.disabled = model.busy;
129	  out.addEventListener('click', () => actions.logout());
130	  section.append(out);
131	  return section;
132	}
133	
134	function note(message: string): HTMLElement {
135	  return text('p', message, { class: 'muted' });
136	}
137	
138	function element(tag: string, attributes: Record<string, string> = {}): HTMLElement {
139	  const node = document.createElement(tag);
140	  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
141	  return node;
142	}
143	
144	/** Text goes in as `textContent`, so nothing the API or a provider said is markup. */
145	function text(tag: string, content: string, attributes: Record<string, string> = {}): HTMLElement {
146	  const node = element(tag, attributes);
147	  node.textContent = content;
148	  return node;
149	}
